function trWord(t){return EN[t]||t}
function trCore(t){
 if(EN[t]!==undefined)return EN[t];
 for(const [rx,rep] of EN_RX){if(rx.test(t))return t.replace(rx,rep)}
 const m=t.match(/^([＋+⌂◷✓]\s?)(.+)$/);if(m&&EN[m[2]])return m[1]+EN[m[2]];
 if(t.endsWith(':')&&EN[t.slice(0,-1)])return EN[t.slice(0,-1)]+':';
 return null;
}

