function tr(str){
 if(LANG!=='en'||typeof str!=='string')return str;
 const t=str.trim();if(!t||!/[A-Za-zÄÖÜäöüß]/.test(t))return str;
 let out=trCore(t);
 // Zusammengesetzte Texte „A · B · C“ teilweise übersetzen (z. B. Rolle · Team)
 if(out===null&&t.includes(' · ')){const parts=t.split(' · ');const tp=parts.map(p=>trCore(p)??p);if(tp.some((x,i)=>x!==parts[i]))out=tp.join(' · ');}
 if(out===null)return str;
 return str.replace(t,out);
}
const TR_ATTRS=['placeholder','title','aria-label','data-label'];
function translateNode(root){
 if(LANG!=='en'||!root)return;
 if(root.nodeType===3){const v=tr(root.nodeValue);if(v!==root.nodeValue)root.nodeValue=v;return}
 if(root.nodeType!==1)return;
 if(root.closest&&root.closest('script,style,[data-no-translate]'))return;
 TR_ATTRS.forEach(a=>{if(root.hasAttribute&&root.hasAttribute(a)){const v=root.getAttribute(a),n=tr(v);if(n!==v)root.setAttribute(a,n)}});
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let n;
 while((n=w.nextNode())){
  if(n.nodeType===3){if(n.parentElement&&n.parentElement.closest('script,style,[data-no-translate]'))continue;const v=tr(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v;}
  else TR_ATTRS.forEach(a=>{if(n.hasAttribute(a)){const v=n.getAttribute(a),x=tr(v);if(x!==v)n.setAttribute(a,x)}});
 }
}
if(LANG==='en'){
 document.title='DienstPlan Pro – Duty & on-call management';
 const start=()=>{
  translateNode(document.body);
  new MutationObserver(list=>{for(const m of list){if(m.type==='characterData')translateNode(m.target);else if(m.type==='attributes')translateNode(m.target);else m.addedNodes.forEach(translateNode)}})
   .observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:TR_ATTRS});
 };
 if(document.body)start();else document.addEventListener('DOMContentLoaded',start);
}

